WITH exploded AS (SELECT id, currency, EXPLODE(tier_prices) AS element FROM price_tiers) SELECT CASE WHEN element >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, currency, COUNT(*) AS event_count, COUNT_IF(currency = 'EUR') AS eur_events, COUNT(*) AS num_rows, AVG(element) AS avg_element FROM exploded GROUP BY CASE WHEN element >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END, currency;
